      "rubric": {
        "tier_0": "成年男性不在中央或主导位置，或其体格/年龄与较年轻男性无明显差异。",
        "tier_1": "成年男性略偏但体量较大，或年龄差异可见但体格差异不足；主导关系不够明确。",
        "tier_2": "成年男性清晰位于群像中央或视觉主导位置，且体格与年龄明显大于较年轻男性。"
      },
      "variants_used": "无变体。",
      "visibility_requirement": "题面要求正面全景，应可见群像布局；若群像被裁切到无法判断相对位置，则0分；若可判断但差异不足，则1分。",
      "weight": 1.0
    },
    {
      "check": "成年男性与较年轻男性均须呈现因蛇袭导致的挣扎、扭转、痛苦紧张状态，而非安静放松；可通过面部表情、身体姿态或肌肉紧绷任一方式表现。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
