      "rubric": {
        "tier_0": "拉奥孔被表现为女性，或出现明显女性第二性征。",
        "tier_1": "性别表现模糊，但无明确女性第二性征，难以确认其为成年男性。",
        "tier_2": "拉奥孔明确为成年男性，且无女性第二性征。"
      },
      "variants_used": "无变体。",
      "visibility_requirement": "正面完整构图下应可见面部与躯干；若完全不可见导致无法确认，则0分；若可判断但性别特征模糊，则1分。",
      "weight": 1.0
    },
    {
      "check": "人物须以裸身或仅有少量遮体布料的古典男性人体形式出现。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
