  "alignment_checks": [
    {
      "check": "题面指定“拉奥孔主题白色大理石作品”为画面主体，要求该主体占据视觉主导地位。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "画面没有可识别的拉奥孔主题主体，或主体被背景、杂物严重挤占。",
        "tier_1": "主体可见但体量偏小、位置偏边，视觉焦点不够集中。",
        "tier_2": "拉奥孔主题主体占据画面核心视觉位置，体量与焦点均明显主导。"
      }
    },
    {
      "check": "题面指定主体为白色大理石作品，材质应呈现白色石质/大理石质感。",
      "facet": "material_properties",
      "rubric": {
        "tier_0": "主体明显不是白色，也不是石质或大理石质感。",
        "tier_1": "主体接近白色或石质，但材质表现不稳定、局部像金属/塑料/织物。",
        "tier_2": "主体整体呈白色大理石质感，石质表面与材料属性清晰可信。"
      }
    },
    {
      "check": "题面指定场景为博物馆展厅，主体立于基座上，背景为简洁米色墙面。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "场景不是博物馆展厅，或缺少基座与简洁米色墙面等关键环境设定。",
        "tier_1": "场景部分符合展厅，但基座、墙面颜色或环境元素混乱、不完整。",
        "tier_2": "场景清楚呈现博物馆展厅环境，主体位于基座上，背景为简洁米色墙面。"
      }
    },
    {
      "check": "题面要求正面全景图且主体完整立于基座上，画面应呈现主体与基座的上下支撑关系并无明显裁切。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "主体被严重裁切，或基座与主体的上下关系错误、无法构成完整陈列。",
        "tier_1": "主体基本可见但局部裁切，或基座关系不够明确。",
        "tier_2": "正面全景下主体完整可见，位于基座上方，支撑与空间关系清楚。"
      }
